<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';import * as pdfjs from 'pdfjs-dist';import workerUrl from 'pdfjs-dist/build/pdf.worker.min.mjs?url';
pdfjs.GlobalWorkerOptions.workerSrc=workerUrl;const props=defineProps<{version:any,page?:number,region?:{x:number,y:number,width:number,height:number}}>();const canvas=ref<HTMLCanvasElement>();const error=ref(''),busy=ref(false),current=ref(props.page||1),total=ref(1),pageWidth=ref(612),pageHeight=ref(792);let doc:pdfjs.PDFDocumentProxy|undefined;let task:pdfjs.PDFDocumentLoadingTask|undefined;let renderTask:pdfjs.RenderTask|undefined;
async function render(){if(!doc||!canvas.value)return;try{busy.value=true;const page=await doc.getPage(current.value);const vp=page.getViewport({scale:1.15});pageWidth.value=vp.width/1.15;pageHeight.value=vp.height/1.15;canvas.value.width=vp.width;canvas.value.height=vp.height;renderTask=page.render({canvas:canvas.value,viewport:vp});await renderTask.promise;}catch(e:any){if(e.name!=='RenderingCancelledException')error.value='Preview unavailable. Try the authenticated download.'}finally{busy.value=false}}
async function load(){error.value='';renderTask?.cancel();await task?.destroy();doc=undefined;current.value=props.page||1;if(props.version.mime!=='application/pdf')return;try{task=pdfjs.getDocument({url:'/api/document-versions/'+props.version.id+'/content',withCredentials:true});doc=await task.promise;total.value=doc.numPages;await render()}catch{error.value='Access denied or document could not be previewed.'}}
onMounted(load);watch(()=>props.version.id,load);watch(current,render);onBeforeUnmount(()=>{renderTask?.cancel();task?.destroy().catch(()=>{})});
</script>
<template><section class="viewer"><div class="viewer-toolbar"><strong>{{version.original_name}}</strong><a :href="'/api/document-versions/'+version.id+'/content?download=1'">Download original</a></div><p class="micro warning">Original bytes · {{version.scan_status}} · Fictional samples only</p><p v-if="error" role="alert">{{error}}</p><p v-if="busy" aria-live="polite">Rendering document…</p><div class="canvas-scroll" v-if="version.mime==='application/pdf'"><div class="pdf-page"><canvas ref="canvas" aria-label="PDF source page"/><div v-if="region" class="source-highlight" aria-label="Sample source evidence region" :style="{left:(region.x/pageWidth*100)+'%',top:(region.y/pageHeight*100)+'%',width:(region.width/pageWidth*100)+'%',height:(region.height/pageHeight*100)+'%'}"></div></div></div><img v-else :src="'/api/document-versions/'+version.id+'/content'" alt="Uploaded fictional source document" class="source-image"/><div v-if="version.mime==='application/pdf'" class="viewer-toolbar"><button :disabled="current<=1||busy" @click="current--">Previous</button><span>Page {{current}} of {{total}}</span><button :disabled="current>=total||busy" @click="current++">Next</button></div></section></template>
